package bookstore

import "sort"

// prices[i] is the cost, in cents, of a group of i distinct books.
var prices = []int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the minimum total price, in cents, for the given basket of
// books, giving as big a discount as possible.
func Cost(books []int) int {
	counts := [5]int{}
	for _, book := range books {
		counts[book-1]++
	}

	// Sort the per-title counts in descending order.
	sorted := counts[:]
	sort.Sort(sort.Reverse(sort.IntSlice(sorted)))

	// Build the "staircase" grouping: the j-th group contains one copy of
	// every title whose count exceeds j. This uses the fewest possible
	// groups (equal to the largest count) with the largest possible sizes.
	groups := make([]int, sorted[0])
	for j := range groups {
		for _, c := range sorted {
			if c > j {
				groups[j]++
			}
		}
	}

	// A group of five plus a group of three costs 5160, while two groups of
	// four cost 5120, so trade as many such pairs as possible.
	trades := 0
	for _, size := range groups {
		if size == 5 && trades < countOf(groups, 3) {
			trades++
		}
	}

	cost := 0
	for _, size := range groups {
		if trades > 0 && (size == 5 || size == 3) {
			trades--
			size = 4
		}
		cost += prices[size]
	}
	return cost
}

func countOf(groups []int, size int) int {
	n := 0
	for _, g := range groups {
		if g == size {
			n++
		}
	}
	return n
}

